    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int target = (int) in.nval;
        int[] candidates = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); candidates[i] = (int) in.nval;
        }
        List<List<Integer>> res = combinationSum2(candidates, target);
        for (List<Integer> r : res) Collections.sort(r);
        res.sort((a, b) -> {
            for (int i = 0; i < Math.min(a.size(), b.size()); i++) {
                if (!a.get(i).equals(b.get(i))) return Integer.compare(a.get(i), b.get(i));
            }
            return Integer.compare(a.size(), b.size());
        });
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append("\n");
        for (List<Integer> r : res) {
            for (int i = 0; i < r.size(); i++) sb.append(r.get(i)).append(i + 1 < r.size() ? " " : "\n");
        }
        System.out.print(sb);
    }
}
